22	// ------------------------------------------------------------------
23	// Simple mutex with bounded queue.
24	// lake build writes to a shared file (Verify.lean) so all calls must
25	// be serialised to prevent races.
26	// ------------------------------------------------------------------
27	let buildRunning = false;
28	const buildQueue: Array<{ resolve: () => void; reject: (error: Error) => void }> = [];
29	
30	async function acquireBuildLock(): Promise<void> {
31	  if (!buildRunning) {
32	    buildRunning = true;
33	    return;
34	  }
35	  if (buildQueue.length >= MAX_QUEUE_LENGTH) {
36	    throw new Error("Build queue full — too many concurrent verification requests");
37	  }
38	  return new Promise<void>((resolve, reject) => {
39	    buildQueue.push({ resolve, reject });
40	  });
41	}
42	
43	function releaseBuildLock(): void {
44	  const nextJob = buildQueue.shift();
45	  if (nextJob) {
46	    nextJob.resolve();
47	  } else {
48	    buildRunning = false;
49	  }
50	}
