52	// ------------------------------------------------------------------
53	// Pre-process Lean code before verification.
54	// When combining dependency context with newly generated code, `import Mathlib`
55	// can appear multiple times. Lean rejects duplicate imports, so we keep only
56	// the first occurrence.
57	// ------------------------------------------------------------------
58	
59	function deduplicateImports(code: string): string {
60	  const lines = code.split("\n");
61	  const seenImports = new Set<string>();
62	  const result = lines.filter((line) => {
63	    const trimmed = line.trim();
64	    if (/^import\s+/.test(trimmed)) {
65	      if (seenImports.has(trimmed)) return false;
66	      seenImports.add(trimmed);
67	    }
68	    return true;
69	  });
70	  return result.join("\n");
71	}
