21	export type StreamCallbacks = {
22	  onToken: (accumulated: string) => void;
23	};
24	
25	type StreamResult = {
26	  text: string;
27	  usage: LlmCallUsage;
28	};
29	
30	/**
31	 * Fetch an SSE streaming API route. Sends `{ ...body, stream: true }`,
32	 * reads token events progressively, and returns the final text + usage.
33	 */
34	export async function fetchStreamingApi(
35	  url: string,
36	  body: Record<string, unknown>,
37	  callbacks: StreamCallbacks,
38	): Promise<StreamResult> {
39	  const res = await fetch(url, {
40	    method: "POST",
41	    headers: { "Content-Type": "application/json" },
42	    body: JSON.stringify({ ...body, stream: true }),
43	  });
44	
45	  if (!res.ok) {
46	    const data = await res.json().catch(() => ({ error: "Request failed" }));
47	    throw new Error(data.error ?? "Request failed");
48	  }
49	
50	  const reader = res.body?.getReader();
51	  if (!reader) throw new Error("Response has no body");
52	
53	  const decoder = new TextDecoder();
54	  let buffer = "";
55	  let accumulated = "";
56	  let finalResult: StreamResult | null = null;
57	
58	  for (;;) {
59	    const { done, value } = await reader.read();
60	    if (done) break;
61	
62	    buffer += decoder.decode(value, { stream: true });
63	    const blocks = buffer.split("\n\n");
64	    // Keep the last (potentially incomplete) block in the buffer
65	    buffer = blocks.pop() ?? "";
66	
67	    for (const block of blocks) {
68	      if (!block.trim()) continue;
69	
70	      let eventType = "";
71	      let dataStr = "";
72	      for (const line of block.split("\n")) {
73	        if (line.startsWith("event: ")) eventType = line.slice(7);
74	        else if (line.startsWith("data: ")) dataStr = line.slice(6);
75	      }
76	
77	      if (!eventType || !dataStr) continue;
78	
79	      if (eventType === "token") {
80	        try {
81	          const parsed = JSON.parse(dataStr);
82	          accumulated += parsed.text;
83	          callbacks.onToken(accumulated);
84	        } catch { /* skip malformed */ }
85	      } else if (eventType === "done") {
86	        try {
87	          const parsed = JSON.parse(dataStr);
88	          finalResult = { text: parsed.text, usage: parsed.usage };
89	        } catch { /* skip malformed */ }
90	      } else if (eventType === "error") {
91	        let errorMsg = "Stream error";
92	        try {
93	          errorMsg = JSON.parse(dataStr).error ?? errorMsg;
94	        } catch { /* use default */ }
95	        throw new Error(errorMsg);
96	      }
97	    }
98	  }
99	
100	  if (!finalResult) throw new Error("Stream ended without a done event");
101	  return finalResult;
102	}
