135	  const old = loadWorkspace();
136	  if (!old) return false;
137	
138	  const store = useWorkspaceStore.getState();
139	  store.setSourceText(old.sourceText);
140	  store.setExtractedFiles(old.extractedFiles);
141	  store.setContextText(old.contextText);
142	  store.setSemiformalText(old.semiformalText);
143	  store.setLeanCode(old.leanCode);
144	  store.setSemiformalDirty(old.semiformalDirty);
145	  store.setVerificationStatus(old.verificationStatus);
146	  store.setVerificationErrors(old.verificationErrors);
147	  store.setDecomposition(old.decomposition);
148	
149	  // Migrate flat artifact JSON strings to versioned records
150	  for (const [field, key] of Object.entries(V2_ARTIFACT_FIELDS)) {
151	    const content = old[field as keyof PersistedWorkspace];
152	    if (typeof content === "string" && content) {
153	      store.setArtifactGenerated(key, content);
154	    }
155	  }
156	
157	  return true;
158	}
