164	export const useWorkspaceStore = create<WorkspaceState & WorkspaceActions>()(
165	  persist(
166	    (set, get) => ({
167	      ...DEFAULT_STATE,
168	
169	      // --- Simple setters ---
170	      setSourceText: (v) => set({ sourceText: v }),
171	      setExtractedFiles: (v) => set({ extractedFiles: v }),
172	      setContextText: (v) => set({ contextText: v }),
173	      setSemiformalText: (v) =>
174	        set((s) => ({
175	          semiformalText: typeof v === "function" ? v(s.semiformalText) : v,
176	        })),
177	      setLeanCode: (v) =>
178	        set((s) => ({
179	          leanCode: typeof v === "function" ? v(s.leanCode) : v,
180	        })),
181	      setSemiformalDirty: (v) =>
182	        set((s) => ({
183	          semiformalDirty: typeof v === "function" ? v(s.semiformalDirty) : v,
184	        })),
185	      setVerificationStatus: (v) => set({ verificationStatus: v }),
186	      setVerificationErrors: (v) => set({ verificationErrors: v }),
187	
188	      // --- Artifact versioning ---
189	      setArtifactGenerated: (key, content) =>
190	        set((s) => {
191	          const existing = s.artifacts[key];
192	          const version = makeVersion(content, "generated");
193	          const versions = existing
194	            ? [...existing.versions.slice(-MAX_VERSIONS + 1), version]
195	            : [version];
196	          return {
197	            artifacts: {
198	              ...s.artifacts,
199	              [key]: {
200	                type: key,
201	                currentVersionIndex: versions.length - 1,
202	                versions,
203	              },
204	            },
205	          };
206	        }),
207	
208	      setArtifactEdited: (key, content, source, instruction) =>
209	        set((s) => {
210	          const existing = s.artifacts[key];
211	          if (!existing) {
212	            const version = makeVersion(content, source, instruction);
213	            return {
214	              artifacts: {
215	                ...s.artifacts,
216	                [key]: { type: key, currentVersionIndex: 0, versions: [version] },
217	              },
218	            };
219	          }
220	          // Truncate redo history when making a new edit
221	          const version = makeVersion(content, source, instruction);
222	          const truncated = existing.versions.slice(0, existing.currentVersionIndex + 1);
223	          const versions = [...truncated.slice(-MAX_VERSIONS + 1), version];
224	          return {
225	            artifacts: {
226	              ...s.artifacts,
227	              [key]: {
228	                type: key,
229	                currentVersionIndex: versions.length - 1,
230	                versions,
231	              },
232	            },
233	          };
234	        }),
235	
236	      undoArtifact: (key) =>
237	        set((s) => {
238	          const rec = s.artifacts[key];
239	          if (!rec || rec.currentVersionIndex <= 0) return s;
240	          return {
241	            artifacts: {
242	              ...s.artifacts,
243	              [key]: { ...rec, currentVersionIndex: rec.currentVersionIndex - 1 },
244	            },
245	          };
246	        }),
247	
248	      redoArtifact: (key) =>
249	        set((s) => {
250	          const rec = s.artifacts[key];
251	          if (!rec || rec.currentVersionIndex >= rec.versions.length - 1) return s;
252	          return {
253	            artifacts: {
254	              ...s.artifacts,
255	              [key]: { ...rec, currentVersionIndex: rec.currentVersionIndex + 1 },
256	            },
257	          };
258	        }),
259	
260	      getArtifactContent: (key) => {
261	        const rec = get().artifacts[key];
262	        if (!rec) return null;
263	        return rec.versions[rec.currentVersionIndex]?.content ?? null;
264	      },
265	
266	      canUndo: (key) => {
267	        const rec = get().artifacts[key];
268	        return !!rec && rec.currentVersionIndex > 0;
269	      },
270	
271	      canRedo: (key) => {
272	        const rec = get().artifacts[key];
273	        return !!rec && rec.currentVersionIndex < rec.versions.length - 1;
274	      },
275	
276	      // --- Decomposition ---
277	      setDecomposition: (d) => set({ decomposition: d }),
278	
279	      // --- Snapshot/restore ---
280	      getSnapshot: () => {
281	        const s = get();
282	        return {
283	          sourceText: s.sourceText,
284	          extractedFiles: s.extractedFiles.map(({ name, text }) => ({ name, text })),
285	          contextText: s.contextText,
286	          semiformalText: s.semiformalText,
287	          leanCode: s.leanCode,
288	          semiformalDirty: s.semiformalDirty,
289	          verificationStatus: s.verificationStatus,
290	          verificationErrors: s.verificationErrors,
291	          artifacts: structuredClone(s.artifacts),
292	          decomposition: structuredClone(s.decomposition),
293	        };
294	      },
295	
296	      resetToSnapshot: (data) => set({ ...data }),
297	
298	      clearWorkspace: () => set({ ...DEFAULT_STATE }),
299	    }),
300	    {
301	      name: "workspace-zustand-v1",
302	      storage: createJSONStorage(() => localStorage),
303	      // SSR safe: render defaults first, hydrate in useEffect via rehydrate()
304	      skipHydration: true,
305	      // Only persist data fields, not action functions
306	      partialize: (state) => ({
307	        sourceText: state.sourceText,
308	        extractedFiles: state.extractedFiles.map(({ name, text }) => ({ name, text })),
309	        contextText: state.contextText,
310	        semiformalText: state.semiformalText,
311	        leanCode: state.leanCode,
312	        semiformalDirty: state.semiformalDirty,
313	        verificationStatus: state.verificationStatus,
314	        verificationErrors: state.verificationErrors,
315	        artifacts: state.artifacts,
316	        decomposition: state.decomposition,
317	      }),
318	      // On rehydrate, check if we need to migrate from workspace-v2
319	      onRehydrateStorage: () => {
320	        return (_state, error) => {
321	          if (error) return;
322	          // If Zustand store was empty (no persisted data) but workspace-v2 exists,
323	          // migrate the old data. We check by looking for the old key.
324	          if (typeof window !== "undefined" && localStorage.getItem(WORKSPACE_KEY)) {
